const http = require('http')
const { caches, Request } = require('./index.js')

const server = http.createServer((req, res) => {
  if (req.url === '/404') {
    res.statusCode = 404
    res.end('nope')
  } else if (req.url === '/204') {
    res.statusCode = 204
    res.end()
  } else if (req.url === '/vary-star') {
    res.setHeader('vary', '*')
    res.end('varies')
  } else if (req.url === '/vary') {
    res.setHeader('vary', 'accept')
    res.end('varies on accept')
  } else {
    res.end('body:' + req.url)
  }
})

async function main () {
  const base = 'http://localhost:' + server.address().port
  const cache = await caches.open('t')

  await cache.addAll([base + '/a', base + '/b', new Request(base + '/c')])
  for (const p of ['/a', '/b', '/c']) {
    const res = await cache.match(base + p)
    console.log(p, '->', await res.text())
  }

  const keys = await cache.keys()
  console.log('keys:', keys.length)

  await cache.add(base + '/204')
  const r204 = await cache.match(base + '/204')
  console.log('204 status:', r204.status, JSON.stringify(await r204.text()))

  await cache.add(base + '/vary')
  console.log('vary match:', await (await cache.match(base + '/vary')).text())

  // re-adding the same url should replace, not throw
  await cache.add(base + '/a')
  console.log('re-add ok, keys:', (await cache.keys()).length)

  try {
    await cache.add(base + '/404')
    console.log('FAIL: 404 resolved')
  } catch (e) {
    console.log('404 rejected:', e.name, e.message)
  }

  try {
    await cache.add(base + '/vary-star')
    console.log('FAIL: vary * resolved')
  } catch (e) {
    console.log('vary * rejected:', e.name, e.message)
  }

  try {
    await cache.addAll([base + '/dup', base + '/dup'])
    console.log('FAIL: duplicates resolved')
  } catch (e) {
    console.log('duplicates rejected:', e.name, e.message)
  }

  // body can be read twice from two matches
  const m1 = await cache.match(base + '/b')
  const m2 = await cache.match(base + '/b')
  console.log('two matches:', await m1.text(), await m2.text())

  await caches.delete('t')
  server.close()
}

server.listen(0, () => {
  const t = setTimeout(() => { console.log('HANG'); process.exit(1) }, 10000)
  main().then(() => clearTimeout(t), (e) => { clearTimeout(t); console.error('ERR', e); process.exit(1) })
})

