const http = require('http')
const { caches } = require('./index.js')

process.on('unhandledRejection', (e) => {
  console.log('UNHANDLED REJECTION:', e && e.name, e && e.message)
  process.exit(1)
})

const server = http.createServer((req, res) => {
  if (req.url === '/vary-star') {
    setTimeout(() => {
      res.setHeader('vary', '*')
      res.end('varies')
    }, 100)
  } else {
    res.write('start')
    setTimeout(() => res.end('end'), 500)
  }
})

server.listen(0, async () => {
  const origin = 'http://localhost:' + server.address().port
  const cache = await caches.open('t')
  try {
    await cache.addAll([origin + '/slow', origin + '/vary-star'])
    console.log('FAIL: resolved')
  } catch (e) {
    console.log('rejected as expected:', e.name, e.message)
  }
  await new Promise((resolve) => setTimeout(resolve, 1000))
  console.log('no unhandled rejections')
  await caches.delete('t')
  server.close()
})

