const { caches } = require('./index.js')

const server = http.createServer((req, res) => {
  if (req.url === '/vary-star') {
    setTimeout(() => { res.setHeader('vary', '*'); res.end('varies') }, 100)
  } else if (req.url === '/slow-body') {
    res.write('first chunk')
    setTimeout(() => res.end('last chunk'), 1000)
  } else if (req.url === '/404') {
    res.statusCode = 404
    res.end('not found')
  } else {
    res.end('body of ' + req.url)
  }
})

const t0 = Date.now()
const mark = (label) => console.log(label, Date.now() - t0 + 'ms')

server.listen(0, async () => {
  const origin = 'http://localhost:' + server.address().port
  const cache = await caches.open('t')
  mark('open')
  await cache.add(origin + '/one')
  mark('add one')
  await cache.addAll([origin + '/two', origin + '/three'])
  mark('addAll')
  try { await cache.add(origin + '/404') } catch {}
  mark('404')
  try { await cache.add(origin + '/vary-star') } catch {}
  mark('vary-star')
  try { await cache.addAll([origin + '/slow-body', origin + '/vary-star']) } catch {}
  mark('slow-body+vary-star')
  await caches.delete('t')
  mark('delete')
  server.closeIdleConnections()
  server.close(() => mark('server closed'))
})

