const http = require('http')
const { caches } = require('/tmp/cxbench-undici/7ce2cc15bc-none/index.js')

const server = http.createServer((req, res) => { res.end('hello world') })
server.listen(0, async () => {
  const url = 'http://localhost:' + server.address().port + '/'
  const cache = await caches.open('t')
  const t = setTimeout(() => { console.log('HANG: add did not resolve'); process.exit(1) }, 3000)
  await cache.add(url)
  clearTimeout(t)
  console.log('added ok')
  const res = await cache.match(url)
  console.log('match:', res && await res.text())
  server.close()
})
